import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', 'dev-secret-key-change-me')
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(app.config['DB_PATH'])
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT UNIQUE,
        password_hash TEXT, role TEXT DEFAULT 'user',
        api_key TEXT UNIQUE)''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, owner_id INTEGER,
        title TEXT, content TEXT, classification TEXT,
        FOREIGN KEY(owner_id) REFERENCES users(id))''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        user_id INTEGER, action TEXT, detail TEXT)''')
    db.commit()
    db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
        if not user:
            return jsonify({'error': 'Invalid API key'}), 403
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/search')
@require_api_key
def search_documents():
    query = request.args.get('q', '')
    classification = request.args.get('classification', 'public')
    owner_filter = request.args.get('owner', '')

    # Build search query - classification filter applied for safety
    base_sql = "SELECT id, title, classification, owner_id FROM documents WHERE classification = '" + classification + "'"

    if query:
        base_sql += " AND title LIKE '%" + query + "%'"

    if owner_filter:
        base_sql += " AND owner_id = " + str(owner_filter)

    try:
        db = get_db()
        results = db.execute(base_sql).fetchall()
        # Log the search action
        db.execute('INSERT INTO audit_log (user_id, action, detail) VALUES (?, ?, ?)',
                   (g.current_user['id'], 'search', f'q={query}&class={classification}'))
        db.commit()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>')
@require_api_key
def get_document(doc_id):
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'Not found'}), 404
    if doc['owner_id'] != g.current_user['id'] and g.current_user['role'] != 'admin':
        return jsonify({'error': 'Access denied'}), 403
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
@require_api_key
def create_document():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    db = get_db()
    db.execute('INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)',
               (g.current_user['id'], data['title'], data['content'], data.get('classification', 'public')))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
